package com.thangit.boardinghouse.service;

import static org.assertj.core.api.Assertions.*;
import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.dto.request.lifecycle.RentalLifecycleRequests.*;
import com.thangit.boardinghouse.dto.request.property.AdminPropertyRequests.ChangeStatus;
import com.thangit.boardinghouse.repository.AdminPropertyRepository;
import com.thangit.boardinghouse.repository.AdminTenantRepository;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.service.impl.AdminPropertyServiceImpl;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

@EnabledIfSystemProperty(named="prompt04.mysql",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class RoomLifecycleMysqlTest {
    final DepositLedgerMysqlTest f=new DepositLedgerMysqlTest();
    RoomLifecycleGuard rooms;BookingExpirationService expiry;AdminPropertyServiceImpl properties;
    DepositLedgerMysqlTest.Fixture migrationBooking;long migrationContract;long beforeContracts,beforeBookings,beforeHistory;
    final AuthenticatedUser manager=new AuthenticatedUser(2L,"manager@test.invalid",RoleCode.MANAGER);
    final AuthenticatedUser manager2=new AuthenticatedUser(6L,"manager2@test.invalid",RoleCode.MANAGER);
    @BeforeAll void setup()throws Exception {
        f.setup("prompt04_test_","22");rooms=new RoomLifecycleGuard(f.db);expiry=new BookingExpirationService(f.db,rooms);
        properties=new AdminPropertyServiceImpl(new AdminPropertyRepository(f.db),rooms);
        migrationBooking=f.booking("0");migrationContract=lease(migrationBooking.room(),LocalDate.now().toString(),LocalDate.now().plusYears(1).toString());f.db.sql("UPDATE rental_bookings SET contract_id=:c,status='CONTRACT_CREATED' WHERE id=:id").param("c",migrationContract).param("id",migrationBooking.booking()).update();
        beforeContracts=count("contracts","1=1");beforeBookings=count("rental_bookings","1=1");beforeHistory=count("room_status_history","1=1");
        Flyway.configure().dataSource(f.dataSource).load().migrate();
    }
    long count(String table,String where){return f.db.sql("SELECT COUNT(*) FROM "+table+" WHERE "+where).query(Long.class).single();}
    String status(long room){return f.db.sql("SELECT status FROM rooms WHERE id=:id").param("id",room).query(String.class).single();}
    long version(long room){return f.db.sql("SELECT version FROM rooms WHERE id=:id").param("id",room).query(Long.class).single();}
    DepositLedgerMysqlTest.Fixture free(String next){var x=f.booking("0");f.run(()->f.lifecycle.changeBookingStatus(f.owner,x.booking(),new ChangeBookingStatus("CANCELLED","Chuẩn bị fixture",0L)));
        if("READY".equals(next))f.run(()->rooms.manual(x.room(),next,version(x.room()),"Đã kiểm tra điều kiện khai thác",true,1));
        else if(!"VACANT".equals(next))f.db.sql("UPDATE rooms SET status=:status WHERE id=:id").param("status",next).param("id",x.room()).update();return x;}
    CreateBooking request(DepositLedgerMysqlTest.Fixture x){return new CreateBooking(x.profile(),x.room(),LocalDate.now(),LocalDate.now().plusDays(7),BigDecimal.ZERO,null,null);}
    long book(AuthenticatedUser p,DepositLedgerMysqlTest.Fixture x){return f.inTx(()->f.lifecycle.createBooking(p,request(x)).id());}
    record Active(DepositLedgerMysqlTest.Fixture fixture,long contract,long checkin){}
    Active active(){var x=f.booking("0");long c=f.contract(x,"0");long ci=f.inTx(()->f.lifecycle.prepareCheckin(f.owner,new PrepareCheckin(c,x.booking(),LocalDate.now(),null,null)).id());f.ready(c,ci);f.run(()->f.lifecycle.completeCheckin(f.owner,ci,checkin()));return new Active(x,c,ci);}
    CompleteCheckin checkin(){return new CompleteCheckin(true,true,true,BigDecimal.ZERO,BigDecimal.ZERO,1,"Biên bản bàn giao",1L);}
    long checkout(Active a,String charge){long co=f.inTx(()->f.lifecycle.requestCheckout(f.owner,new RequestCheckout(a.contract,LocalDate.now(),"Kết thúc thuê")).id());var completion=f.readyCheckout(co,f.amount(charge),"Verified damage");f.run(()->f.lifecycle.completeCheckout(f.owner,co,completion));return co;}
    void due(DepositLedgerMysqlTest.Fixture x){f.db.sql("UPDATE rental_bookings SET reservation_start=DATE_SUB(CURRENT_DATE,INTERVAL 3 DAY),reservation_end=CURRENT_DATE WHERE id=:id").param("id",x.booking()).update();}
    void assign(DepositLedgerMysqlTest.Fixture x){f.db.sql("INSERT INTO property_managers(property_id,manager_id) VALUES(:p,2),(:p,6)").param("p",x.property()).update();}
    long lease(long room,String start,String end){return f.insert("INSERT INTO contracts(room_id,tenant_id,code,start_date,end_date,status) VALUES("+room+",5,'"+f.key()+"','"+start+"','"+end+"','PENDING_CONFIRMATION')");}
    int parallel(Runnable a,Runnable b)throws Exception{var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){List<Future<Boolean>> fs=new ArrayList<>();for(Runnable action:List.of(a,b))fs.add(pool.submit(()->{gate.await();try{action.run();return true;}catch(AuthException ex){assertThat(ex.status().value()).isEqualTo(409);return false;}}));gate.countDown();int ok=0;for(var result:fs)if(result.get(30,TimeUnit.SECONDS))ok++;return ok;}}

    @Test void tc01_readyBookingSucceeds(){var x=free("READY");book(f.owner,x);assertThat(status(x.room())).isEqualTo("RESERVED");}
    @Test void tc02_occupiedBookingRejected(){var x=free("OCCUPIED");f.error("ROOM_NOT_AVAILABLE",()->book(f.owner,x));}
    @Test void tc03_maintenanceBookingRejected(){var x=free("MAINTENANCE");f.error("ROOM_NOT_AVAILABLE",()->book(f.owner,x));}
    @Test void tc04_cleaningBookingRejected(){var x=free("CLEANING");f.error("ROOM_NOT_AVAILABLE",()->book(f.owner,x));}
    @Test void tc05_twoManagersProduceOneBooking()throws Exception{var x=free("READY");assign(x);assertThat(parallel(()->book(manager,x),()->book(manager2,x))).isEqualTo(1);assertThat(count("rental_bookings","room_id="+x.room()+" AND status IN ('RESERVED','DEPOSITED','CONTRACT_CREATED')")).isEqualTo(1);assertThat(status(x.room())).isEqualTo("RESERVED");assertThat(count("deposit_transactions","deposit_id IN (SELECT id FROM tenant_deposits WHERE booking_id IN (SELECT id FROM rental_bookings WHERE room_id="+x.room()+"))")).isZero();}
    @Test void tc06_cancelReleasesUncommittedRoom(){var x=f.booking("0");f.run(()->f.lifecycle.changeBookingStatus(f.owner,x.booking(),new ChangeBookingStatus("CANCELLED","Không tiếp tục thuê",0L)));assertThat(status(x.room())).isEqualTo("VACANT");}
    @Test void tc07_cancelNeverReleasesAnotherLease(){var x=f.booking("0");lease(x.room(),LocalDate.now().toString(),LocalDate.now().plusYears(1).toString());f.db.sql("UPDATE rooms SET status='OCCUPIED' WHERE id=:id").param("id",x.room()).update();f.run(()->f.lifecycle.changeBookingStatus(f.owner,x.booking(),new ChangeBookingStatus("CANCELLED","Hủy giữ chỗ xung đột lịch sử",0L)));assertThat(status(x.room())).isEqualTo("OCCUPIED");}
    @Test void tc08_expirationReleasesRoom(){var x=f.booking("0");due(x);assertThat(f.inTx(()->expiry.expire(x.booking()))).isTrue();assertThat(status(x.room())).isEqualTo("VACANT");assertThat(f.db.sql("SELECT status FROM rental_bookings WHERE id=:id").param("id",x.booking()).query(String.class).single()).isEqualTo("EXPIRED");}
    @Test void tc09_expirationIsIdempotentAcrossWorkers()throws Exception{var x=f.booking("0");due(x);var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{gate.await();return f.inTx(()->expiry.expire(x.booking()));});var b=pool.submit(()->{gate.await();return f.inTx(()->expiry.expire(x.booking()));});gate.countDown();assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}assertThat(count("rental_booking_history","booking_id="+x.booking()+" AND new_status='EXPIRED'")).isEqualTo(1);}
    @Test void tc10_convertedBookingIsNeverAutoExpired(){var x=f.booking("0");f.contract(x,"0");due(x);assertThat(f.inTx(()->expiry.expire(x.booking()))).isFalse();assertThat(status(x.room())).isEqualTo("RESERVED");}
    @Test void tc11_overlappingContractRejected(){var x=f.booking("0");lease(x.room(),LocalDate.now().toString(),LocalDate.now().plusYears(1).toString());f.error("CONTRACT_DATE_CONFLICT",()->f.contract(x,"0"));assertThat(count("contracts","room_id="+x.room())).isEqualTo(1);}
    @Test void tc12_extensionRejectsCommittedLease(){var a=active();lease(a.fixture.room(),LocalDate.now().plusYears(1).toString(),LocalDate.now().plusYears(2).toString());f.error("CONTRACT_DATE_CONFLICT",()->f.run(()->rooms.extension(a.contract,LocalDate.now().plusYears(2))));}
    @Test void tc13_validCheckinOccupiesRoom(){var a=active();assertThat(status(a.fixture.room())).isEqualTo("OCCUPIED");assertThat(f.db.sql("SELECT status FROM contracts WHERE id=:id").param("id",a.contract).query(String.class).single()).isEqualTo("ACTIVE");}
    @Test void tc14_preparedCheckinBlockedByMaintenance(){var x=f.booking("0");long c=f.contract(x,"0");long ci=f.inTx(()->f.lifecycle.prepareCheckin(f.owner,new PrepareCheckin(c,x.booking(),LocalDate.now(),null,null)).id());f.run(()->rooms.transition(x.room(),"MAINTENANCE","Phát hiện hư hỏng",1L));f.error("ROOM_NOT_READY_FOR_CHECKIN",()->f.run(()->f.lifecycle.completeCheckin(f.owner,ci,checkin())));}
    @Test void tc15_cannotCheckinTwice(){var a=active();f.error("CONTRACT_NOT_READY_FOR_CHECKIN",()->f.run(()->f.lifecycle.completeCheckin(f.owner,a.checkin,checkin())));assertThat(count("room_status_history","room_id="+a.fixture.room()+" AND new_status='OCCUPIED'")).isEqualTo(1);}
    @Test void tc16_noticeIsStillOccupied(){var a=active();f.inTx(()->f.lifecycle.requestCheckout(f.owner,new RequestCheckout(a.contract,LocalDate.now().plusDays(7),"Báo trước trả phòng")));assertThat(status(a.fixture.room())).isEqualTo("NOTICE");f.error("ROOM_NOT_AVAILABLE",()->book(f.owner,a.fixture));}
    @Test void tc17_handoverRequiresTurnover(){var a=active();checkout(a,"0");assertThat(status(a.fixture.room())).isEqualTo("CLEANING");var b=active();checkout(b,"400000");assertThat(status(b.fixture.room())).isEqualTo("MAINTENANCE");}
    @Test void tc18_readinessRequiresExplicitInspection(){var a=active();checkout(a,"0");long version=version(a.fixture.room());f.error("ROOM_READINESS_CONFIRMATION_REQUIRED",()->f.run(()->properties.changeStatus(f.owner,a.fixture.room(),new ChangeStatus("READY","Chưa xác nhận kiểm tra",version,false))));f.run(()->properties.changeStatus(f.owner,a.fixture.room(),new ChangeStatus("READY","Vệ sinh và tài sản đã đạt",version,true)));assertThat(status(a.fixture.room())).isEqualTo("READY");}
    @Test void tc19_manualVacantCannotEvictTenant(){var a=active();f.error("ROOM_STATUS_TRANSITION_INVALID",()->f.run(()->properties.changeStatus(f.owner,a.fixture.room(),new ChangeStatus("VACANT","Thử ghi đè",version(a.fixture.room()),false))));assertThat(status(a.fixture.room())).isEqualTo("OCCUPIED");}
    @Test void tc20_roomOutsideAssignmentIsForbidden(){var x=free("READY");f.error("PROPERTY_ACCESS_DENIED",()->book(manager,x));assertThat(status(x.room())).isEqualTo("READY");}
    @Test void tc21_concurrentManualTransitionsRespectVersion()throws Exception{var x=free("READY");assign(x);long v=version(x.room());assertThat(parallel(()->f.run(()->properties.changeStatus(manager,x.room(),new ChangeStatus("MAINTENANCE","Kiểm tra kỹ thuật",v,false))),()->f.run(()->properties.changeStatus(manager2,x.room(),new ChangeStatus("INACTIVE","Ngừng khai thác",v,false))))).isEqualTo(1);assertThat(version(x.room())).isEqualTo(v+1);}
    @Test void tc22_roomTransitionsHaveActorTimeAndReason(){var a=active();checkout(a,"0");assertThat(count("room_status_history","room_id="+a.fixture.room()+" AND actor_id=1 AND reason IS NOT NULL AND created_at IS NOT NULL")).isEqualTo(4);}
    @Test void tc23_migrationPreservesHistoryAndContracts(){assertThat(count("contracts","id="+migrationContract)).isEqualTo(1);assertThat(count("rental_bookings","id="+migrationBooking.booking()+" AND contract_id="+migrationContract)).isEqualTo(1);assertThat(count("room_status_history","room_id="+migrationBooking.room())).isEqualTo(1);assertThat(count("flyway_schema_history","version='23' AND success=1")).isEqualTo(1);assertThat(beforeContracts).isEqualTo(3);assertThat(beforeBookings).isEqualTo(1);assertThat(beforeHistory).isEqualTo(1);}
    @Test void tc24_expiredPaidBookingPreservesHeldMoney(){var x=f.booking("500000");f.run(()->f.ledger.collect(f.accountant,x.deposit(),f.key(),f.cash("500000")));due(x);f.run(()->expiry.expire(x.booking()));assertThat(f.balance(x.deposit())).isEqualByComparingTo("500000");assertThat(count("deposit_transactions","deposit_id="+x.deposit()+" AND transaction_type='REFUND'")).isZero();assertThat(count("expired_booking_money_to_resolve","booking_id="+x.booking())).isEqualTo(1);}
    @Test void adjacentHalfOpenIntervalsDoNotOverlap(){var x=f.booking("0");LocalDate end=LocalDate.now().plusDays(10);lease(x.room(),LocalDate.now().toString(),end.toString());f.run(()->rooms.contractDates(x.room(),end,end.plusDays(10),null,x.booking()));}
    @Test void validBookingExtensionIsRespectedByExpiry(){var x=f.booking("0");f.run(()->f.lifecycle.extendBooking(f.owner,x.booking(),new ExtendBooking(LocalDate.now().plusDays(30),"Đã thống nhất gia hạn",0L)));assertThat(f.inTx(()->expiry.expire(x.booking()))).isFalse();assertThat(status(x.room())).isEqualTo("RESERVED");}
    @Test void staleBookingCannotCreateContract(){var x=f.booking("0");due(x);f.error("BOOKING_EXPIRED",()->f.contract(x,"0"));}
    @Test void parallelContractCreationUsesOneBookingOnce()throws Exception{var x=f.booking("0");assertThat(parallel(()->f.contract(x,"0"),()->f.contract(x,"0"))).isEqualTo(1);assertThat(count("contracts","room_id="+x.room())).isEqualTo(1);}
    @Test void newLeaseAllowedAfterHandoverAndReadinessBeforeRefundClosure(){var a=active();checkout(a,"400000");f.repairAndAccept(a.fixture.room());f.run(()->properties.changeStatus(f.owner,a.fixture.room(),new ChangeStatus("READY","Đã khắc phục và nghiệm thu",version(a.fixture.room()),true)));long b=book(f.owner,a.fixture);assertThat(b).isPositive();assertThat(count("contracts","id="+a.contract+" AND status='SETTLING'")).isEqualTo(1);}
    @Test void expiredUnhandedLeaseStillBlocksBooking(){var x=free("READY");long c=lease(x.room(),LocalDate.now().minusYears(1).toString(),LocalDate.now().minusDays(1).toString());f.db.sql("UPDATE contracts SET status='EXPIRED' WHERE id=:id").param("id",c).update();f.error("ROOM_ALREADY_COMMITTED",()->book(f.owner,x));}
    @Test void unresolvedMaintenanceBlocksReadiness(){var x=free("MAINTENANCE");f.insert("INSERT INTO maintenance_requests(property_id,room_id,tenant_id,code,title,description,issue_type,priority,status) VALUES("+x.property()+","+x.room()+",5,'"+f.key()+"','Test','Repair','OTHER','HIGH','COMPLETED')");f.error("ROOM_MAINTENANCE_PENDING",()->f.run(()->properties.changeStatus(f.owner,x.room(),new ChangeStatus("READY","Chờ nghiệm thu kỹ thuật",version(x.room()),true))));}
    @Test void residentRegistrationCannotFabricateOccupancy(){var x=free("READY");var repository=new AdminTenantRepository(f.db,rooms);f.error("RESIDENCE_CONTRACT_REQUIRED",()->f.run(()->repository.createResidence(x.profile(),x.property(),x.room(),null,LocalDate.now(),"REPRESENTATIVE",1)));assertThat(status(x.room())).isEqualTo("READY");}
    @Test void maintenanceAfterReadinessReturnsRoomToMaintenance(){var x=free("READY");f.run(()->rooms.maintenanceOpened(x.room(),1));assertThat(status(x.room())).isEqualTo("MAINTENANCE");}
    @Test void approvedExtensionUpdatesDatesOnce(){var a=active();LocalDate end=LocalDate.now().plusYears(2);long req=f.insert("INSERT INTO contract_extension_requests(contract_id,tenant_id,requested_end_date) VALUES("+a.contract+",5,'"+end+"')");var changes=new ContractChangeService(f.db,rooms,f.lifecycle,f.ledger,f.onboarding,f.checkoutWorkflow);long q=f.inTx(()->changes.legacyOffer(f.owner,a.contract,req,"Both parties agree"));var row=f.db.sql("SELECT * FROM contract_change_requests WHERE id=:id").param("id",q).query().singleRow();long version=((Number)row.get("version")).longValue();assertThat(f.db.sql("SELECT end_date FROM contracts WHERE id=:id").param("id",a.contract).query(LocalDate.class).single()).isBefore(end);f.run(()->changes.confirm(f.tenant,q,new ContractChangeService.Confirm(version,row.get("content_hash").toString())));f.run(()->changes.applyExtension(f.owner,q,new ContractChangeService.Action(version,"Apply confirmed annex")));assertThat(f.db.sql("SELECT end_date FROM contracts WHERE id=:id").param("id",a.contract).query(LocalDate.class).single()).isEqualTo(end);f.error("EXTENSION_ALREADY_REVIEWED",()->f.run(()->changes.legacyOffer(f.owner,a.contract,req,"Retry")));}
    @Test void coOccupantDoesNotCreateExclusiveLeaseOrReleaseRepresentativeRoom(){var a=active();f.db.sql("UPDATE rooms SET capacity=2 WHERE id=:id").param("id",a.fixture.room()).update();String code=f.key();long profile=f.insert("INSERT INTO tenant_profiles(tenant_code,full_name,phone) VALUES('"+code.substring(0,20)+"','Member','"+code.substring(0,18)+"')");var repo=new AdminTenantRepository(f.db,rooms);f.run(()->repo.createResidence(profile,a.fixture.property(),a.fixture.room(),null,LocalDate.now(),"OCCUPANT",1));assertThat(count("contracts","room_id="+a.fixture.room())).isEqualTo(1);long residence=f.db.sql("SELECT id FROM tenant_residences WHERE tenant_profile_id=:id AND room_id=:room").param("id",profile).param("room",a.fixture.room()).query(Long.class).single();f.run(()->repo.moveOut(profile,residence,a.fixture.room(),a.contract,LocalDate.now(),"Người ở cùng rời phòng",false,1));assertThat(status(a.fixture.room())).isEqualTo("OCCUPIED");}
}
